modules[S(48)] = function()
return function(import)
local Players = game:GetService(S(223))
local log = import(S(253))
local reported = {}
local function getContainer()
    local playerGui = Players.LocalPlayer:FindFirstChild(S(433))
    local mineGui = playerGui and playerGui:FindFirstChild(S(100))
    local hotbar = mineGui and mineGui:FindFirstChild(S(558))
    local content = hotbar and hotbar:FindFirstChild(S(138))
    return content and content:FindFirstChild(S(73))
end
local function readCount(slotFrame)
    for _, descendant in ipairs(slotFrame:GetDescendants()) do
        if descendant:IsA(S(456)) then
            local count = descendant.Text:match(S(26))
            if count then
                return tonumber(count)
            end
        end
    end
    return nil
end
local function readSlot(slotFrame)
    local itemFrame = slotFrame:FindFirstChild(S(207))
    if not (itemFrame and itemFrame.Visible) then
        return nil
    end
    local content = itemFrame:FindFirstChild(S(468))
    local nameLabel = content and content:FindFirstChild(S(320))
    local damageLabel = content and content:FindFirstChild(S(133))
    if not (nameLabel and damageLabel) or nameLabel.Text == S(141) then
        return nil
    end
    return {
        name = nameLabel.Text,
        power = tonumber((damageLabel.Text:gsub(S(55), S(190)))) or 0,
        count = readCount(slotFrame),
    }
end
local function getMinerSlots()
    local container = getContainer()
    if not container then
        return {}
    end
    local slots = {}
    for _, slotFrame in ipairs(container:GetChildren()) do
        local slot = tonumber(slotFrame.Name)
        if slot and slot >= 1 and slot <= 9 then
            local info = readSlot(slotFrame)
            if info and (info.count == nil or info.count > 0) then
                info.slot = slot
                local key = info.name .. S(499) .. slot
                if not reported[key] then
                    reported[key] = true
                    log(S(215) .. slot .. S(473) .. info.name
                        .. S(266) .. info.power .. S(315) .. tostring(info.count))
                end
                table.insert(slots, info)
            end
        end
    end
    table.sort(slots, function(a, b)
        return a.power > b.power
    end)
    return slots
end
return getMinerSlots
end
end
